const assert=require('node:assert/strict');
const fs=require('node:fs'),read=p=>fs.readFileSync(p,'utf8');
const app=read('app.js'),schema=read('services/schemaService.js');
const debt=read('routes/debts.js'),closing=read('routes/closing.js'),view=read('views/closing/index.ejs');
const snapshot=read('scripts/audit-finance-snapshot.js'),workflow=read('.github/workflows/deploy.yml');
assert.match(schema,/async function ensureV65Schema/);
assert.match(app,/await ensureV65Schema\(\)/);
assert.match(schema,/UNIQUE KEY uq_financing_payment\(debt_payment_id\)/);
assert.doesNotMatch(debt,/INSERT INTO finance_debt_cash_movements/);
assert.match(debt,/installment_number/);
assert.match(debt,/financialAudit\(\{conn,userId:req\.session\.user\.id,action:'record_debt_installment'/);
assert.match(debt,/if\(financing\)throw new Error/);
assert.match(closing,/manual_carry_kbg/);
assert.match(view,/name="manual_carry_kbg"/);
assert.match(snapshot,/diagnoseClosingMismatches/);
assert.match(snapshot,/--report-only/);
assert.match(workflow,/audit-finance-snapshot\.js --report-only/);
assert.doesNotMatch(workflow,/continue-on-error: true/);
console.log('PASS finance reconciliation contracts; actual physical bank/cash balances require external verification');
